import math

# 输入获取
n = int(input())
m = int(input())


# 判断两个数是否互质，辗转相除
def isRelativePrime(x, y):
    while y > 0:
        mod = x % y
        x = y
        y = mod

    return x == 1


# 算法入口
def getResult():
    ans = []

    k = math.ceil(math.sqrt(m))

    for y in range(1, k):
        for x in range(y + 1, k):
            # 互质勾股数
            if isRelativePrime(x, y) and (x + y) % 2 == 1:
                a = x * x - y * y
                b = 2 * x * y
                c = x * x + y * y

                if a >= n and b >= n and c <= m:
                    ans.append([a, b, c] if a < b else [b, a, c])

    if len(ans) > 0:
        ans.sort()
        for lst in ans:
            print(" ".join(map(str, lst)))
    else:
        print("NA")


# 算法调用
